putenv('ANI_SMS_TEST_WP='.dirname(__DIR__,3).'/runtime/wordpress');require __DIR__.'/bootstrap.php';
$store=new AniSms\Infrastructure\Database($wpdb);$store->migrate();add_filter('pre_wp_mail','__return_true');$home=get_option('home');$credential=get_option('ani_sms_credential');$now=time();$calls=0;
update_option('home','https://example.test');update_option('ani_sms_modules',array('auth','marketing','cart'));update_option('ani_sms_cart_settings',AniSms\Cart\Service::validate(array('cart_line'=>'300012345','cart_message'=>'{item_count} {cart_url}','cart_delay'=>'15')));update_option('ani_sms_credential',(new AniSms\Security\Secrets())->encrypt('test-only-cart-key'));
