$user=wp_insert_user(array('user_login'=>'ani_cart_live_'.bin2hex(random_bytes(5)),'user_pass'=>wp_generate_password(30),'role'=>'subscriber'));$phone='+98914'.random_int(1000000,9999999);$store->insert('identities',array('phone'=>$phone,'user_id'=>$user,'verified_at'=>time(),'verification_mode'=>'local'));$queue=new AniSms\Infrastructure\Queue($store);$service=new AniSms\Cart\Service($store,$queue,static function()use(&$now){return $now;});$queue->register('cart',array($service,'dispatch'));add_action('ani_sms_job_finished',function($j,$r)use($service){if('cart'===$j['module'])$service->completed($j,$r);},10,2);
$p=new WC_Product_Simple();$p->set_name('Cart mocked bulk fixture');$p->set_status('publish');$p->set_regular_price('100');$p->set_price('100');$p->set_stock_status('instock');$p->save();$items=array('fixture'=>array('product_id'=>$p->get_id(),'variation_id'=>0,'quantity'=>1,'variation'=>array()));update_user_meta($user,'_woocommerce_persistent_cart_'.get_current_blog_id(),array('cart'=>$items));
try{
 ani_rejects(fn()=>$service->preference($user,true),'local phone proof cannot grant live cart intent');$store->query($wpdb->prepare("UPDATE {$store->table('identities')} SET verification_mode='live' WHERE user_id=%d",$user));ani_rejects(fn()=>$service->preference($user,true),'live OTP alone is not marketing consent');(new AniSms\Marketing\Subscribers($store))->consent($user,true,AniSms\Marketing\Subscribers::VERSION);$service->preference($user,true);$service->activity($user,$items);ani_check('live'===$service->row($user,'live')['mode'],'live episode mode immutable');
 $now+=901;$service->recover();$store->query("UPDATE {$store->table('jobs')} SET available=0 WHERE module='cart'");$queue->drain();ani_check(1===$calls&&'accepted'===$service->row($user,'live')['state'],'accepted only through mocked bulk transport');
 update_option('home','http://example.test');ani_rejects(fn()=>$service->preference($user,true),'HTTPS required for live cart consent');update_option('home','https://example.test');
 $now+=7*DAY_IN_SECONDS+2;$service->activity($user,$items);$r=$service->row($user,'live');$order=new WC_Order();$order->set_customer_id($user);$order->set_status('pending');$order->set_date_created($now);$order->save();
 // Restore a waiting revision to simulate a missed order callback; dispatch must reconcile CRUD state.
